package com.nora.tunnel.ui.screens.security import androidx.compose.foundation.layout.* import androidx.compose.material3.* import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.compose.ui.unit.dp @Composable fun SecurityCenter(state: String = "ACTIVE") { Column(Modifier.fillMaxSize().padding(16.dp)) { Text("Security Center", style=MaterialTheme.typography.headlineSmall) listOf("VPN Interface" to state, "Encryption" to "ACTIVE", "DNS Protection" to "NOT CONFIGURED", "IPv6" to "DISABLED", "Kill Switch" to "ENABLED").forEach{(k,v)-> ListItem(headlineContent={Text(k)}, trailingContent={ Text(v, color=if(v=="ACTIVE"||v=="ENABLED") MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error) }) Divider() } Text("Always-on VPN guidance: Settings → VPN → Nora Tunnel → Always-on + Block without VPN", style=MaterialTheme.typography.bodySmall, modifier=Modifier.padding(top=12.dp)) } }

